    13	/**
    14	 * Translates the JSON scenario protocol into MHPCO operations and back.
    15	 * The protocol field names are binding; the premium rules live in
    16	 * {@link PremiumPolicy}.
    17	 */
    18	public class ClaimOfficeCli {
    19	
    20	    private static final ObjectMapper JSON = new ObjectMapper();
    21	
    22	    private final PremiumPolicy premiumPolicy = new PremiumPolicy();
    23	
    24	    public void run(InputStream scenario, PrintStream results) {
    25	        try {
    26	            JsonNode input = JSON.readTree(scenario);
    27	            int yearsWithMHPCO = input.get("customer").get("yearsWithMHPCO").asInt();
    28	            ObjectNode output = JSON.createObjectNode();
    29	            ArrayNode resultsNode = output.putArray("results");
    30	            int contractsAlreadyHeld = 0;
    31	            for (JsonNode step : input.get("steps")) {
    32	                Customer customer = new Customer(yearsWithMHPCO, contractsAlreadyHeld);
    33	                resultsNode.addObject().put("premium",
    34	                        premiumPolicy.quote(customer, insuredItems(step)));
    35	                contractsAlreadyHeld++;
    36	            }
    37	            results.print(JSON.writeValueAsString(output));
    38	        } catch (IOException e) {
    39	            throw new UncheckedIOException(e);
    40	        }
    41	    }
    42	
    43	    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
    44	        List<InsuredItem> items = new ArrayList<>();
    45	        for (JsonNode item : quoteStep.get("items")) {
    46	            items.add(new InsuredItem(item.get("type").asText(),
    47	                    item.path("cursed").asBoolean(false),
    48	                    item.path("enchantment").asInt(0)));
    49	        }
    50	        return items;
    51	    }
    52	}
