     1	import java.math.BigDecimal;
     2	import java.math.RoundingMode;
     3	import java.util.List;
     4	
     5	/**
     6	 * The MHPCO premium rules: the two scopes of premium modifier, the processing
     7	 * fee, and rounding in the office's favor, applied to the base premium the
     8	 * {@link PriceList} states for the insured items.
     9	 *
    10	 * Intermediate amounts stay exact fractions; only the final premium is rounded.
    11	 */
    12	public class PremiumPolicy {
    13	
    14	    private static final BigDecimal CURSE_SURCHARGE_RATE = new BigDecimal("0.50");
    15	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = new BigDecimal("0.30");
    16	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = new BigDecimal("0.10");
    17	    private static final BigDecimal LOYALTY_DISCOUNT_RATE = new BigDecimal("0.20");
    18	    private static final BigDecimal FOLLOW_UP_CONTRACT_DISCOUNT_RATE = new BigDecimal("0.15");
    19	    private static final BigDecimal PROCESSING_FEE = new BigDecimal("5");
    20	
    21	    private final PriceList priceList = new PriceList();
    22	
    23	    /**
    24	     * The office charges both kinds of modifier on a base premium, never on each
    25	     * other: an item modifier on the affected item's own base premium, a
    26	     * policy-wide modifier on the policy base premium. So the two are summed
    27	     * alongside the base premium rather than compounded in sequence, and the
    28	     * processing fee is added at the very end.
    29	     */
    30	    public int quote(Customer customer, List<InsuredItem> insuredItems) {
    31	        BigDecimal policyBasePremium = priceList.policyBasePremium(insuredItems);
    32	        BigDecimal premium = policyBasePremium
    33	                .add(itemRiskSurcharges(insuredItems))
    34	                .add(policyWideModifiers(policyBasePremium, customer))
    35	                .add(PROCESSING_FEE);
    36	        return inOfficesFavor(premium);
    37	    }
    38	
    39	    /**
    40	     * Item-scope modifiers: each is charged on the base premium of the affected
    41	     * item alone, so a modifier on one item never touches another item's share
    42	     * of the policy. What one item's risks cost is {@link #riskSurcharge}'s
    43	     * business; this rule only states that the policy owes the sum of them.
    44	     */
    45	    private BigDecimal itemRiskSurcharges(List<InsuredItem> insuredItems) {
    46	        BigDecimal surcharges = BigDecimal.ZERO;
    47	        for (InsuredItem insuredItem : insuredItems) {
    48	            surcharges = surcharges.add(riskSurcharge(insuredItem));
    49	        }
    50	        return surcharges;
    51	    }
    52	
    53	    /**
    54	     * What the risks the office reads in one item cost, charged on that item's
    55	     * own base premium. A curse and a high enchantment are separate risks, so an
    56	     * item carrying both is surcharged for both rather than letting the graver
    57	     * risk absorb the other.
    58	     */
    59	    private BigDecimal riskSurcharge(InsuredItem insuredItem) {
    60	        BigDecimal itemBasePremium = priceList.basePremium(insuredItem);
    61	        BigDecimal surcharge = BigDecimal.ZERO;
    62	        if (insuredItem.cursed()) {
    63	            surcharge = surcharge.add(itemBasePremium.multiply(CURSE_SURCHARGE_RATE));
    64	        }
    65	        if (insuredItem.isHighlyEnchanted()) {
    66	            surcharge = surcharge.add(itemBasePremium.multiply(HIGH_ENCHANTMENT_SURCHARGE_RATE));
    67	        }
    68	        return surcharge;
    69	    }
    70	
    71	    /**
    72	     * Policy-scope modifiers: each is charged on the policy base premium, the
    73	     * sum of all item base premiums. Every quote is a first insurance of the
    74	     * items it covers, whatever the customer's history.
    75	     */
    76	    private BigDecimal policyWideModifiers(BigDecimal policyBasePremium, Customer customer) {
    77	        return firstInsuranceSurcharge(policyBasePremium)
    78	                .subtract(loyaltyDiscount(policyBasePremium, customer))
    79	                .subtract(followUpContractDiscount(policyBasePremium, customer));
    80	    }
    81	
    82	    /**
    83	     * Every contract after the customer's first earns a discount, however long
    84	     * they have been with the office.
    85	     */
    86	    private static BigDecimal followUpContractDiscount(BigDecimal policyBasePremium,
    87	            Customer customer) {
    88	        if (!customer.holdsFollowUpContract()) {
    89	            return BigDecimal.ZERO;
    90	        }
    91	        return policyBasePremium.multiply(FOLLOW_UP_CONTRACT_DISCOUNT_RATE);
    92	    }
    93	
    94	    /**
    95	     * Every quote is a first insurance of the items it covers, whatever the
    96	     * customer's history, so this surcharge is charged on every policy.
    97	     */
    98	    private static BigDecimal firstInsuranceSurcharge(BigDecimal policyBasePremium) {
    99	        return policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE);
   100	    }
   101	
   102	    /**
   103	     * The office rewards a long-standing customer with a discount on the policy
   104	     * base premium. Who counts as long-standing is the customer's standing to
   105	     * answer; this rule only states what that standing is worth.
   106	     */
   107	    private static BigDecimal loyaltyDiscount(BigDecimal policyBasePremium, Customer customer) {
   108	        if (!customer.isLongStanding()) {
   109	            return BigDecimal.ZERO;
   110	        }
   111	        return policyBasePremium.multiply(LOYALTY_DISCOUNT_RATE);
   112	    }
   113	
   114	    /** The office rounds a premium up, never down: a fraction of a G favors the office. */
   115	    private static int inOfficesFavor(BigDecimal premium) {
   116	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
   117	    }
   118	}
