import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * Rounding in the MHPCO's favor: the office never loses a fraction of a G.
 *
 * Which way that falls depends on which side of the ledger the amount sits on,
 * so the direction is this rule's to decide rather than each calculation's: a
 * premium the customer owes is rounded up, a payout the office owes is rounded
 * down. Intermediate amounts are left exact; only a final amount is rounded.
 */
final class OfficesFavor {

    private OfficesFavor() {
    }

    /** A premium the customer owes rounds up: the office keeps the fraction. */
    static int premium(BigDecimal premium) {
        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
    }
}
